    public Vector2 automation_point_position(Control o,Settings info,Settings point,double y){double fraction=Math.Clamp((N(point,"value")-N(info,"minimum"))/Math.Max(.000001,N(info,"maximum")-N(info,"minimum")),0,1);return new Vector2((float)x_at(o,N(info,"offset")+N(point,"time")),(float)(y+N(o,"track_height")-12-fraction*(N(o,"track_height")-28)));}
