    public void finish_automation_edit(Control o,bool keep){var owner=o.Get("_lane_session").AsGodotObject();var before=o.Get("_lane_before").AsGodotObject();o.Set("_lane_id","");o.Set("_lane_point",new Settings());o.Set("_lane_session",default(Variant));o.Set("_lane_before",default(Variant));if(owner!=null&&before!=null&&owner.Get("_before").AsGodotObject()==before){if(keep&&owner.Get("_pending_preview").AsBool())owner.Call("commit");else owner.Call("cancel");}o.QueueRedraw();}
